-- 642 educational organizations listed for Order No. 27 of 22.01.2026.
-- Generated by scripts/parse-mincifry-education-directory.py from the official PDF text.
ALTER TABLE education_directory
  ADD COLUMN listed_in_mincifry_order_27 BOOLEAN NOT NULL DEFAULT FALSE;

CREATE TEMP TABLE mincifry_order_27_import (
  name TEXT PRIMARY KEY,
  program_codes TEXT[] NOT NULL
) ON COMMIT DROP;


-- Reuse one monitoring row with the same legal-name core, preserving its region and links.
WITH exact_matches AS (
  SELECT DISTINCT ON (src.name) d.id,src.program_codes
  FROM mincifry_order_27_import src
  JOIN education_directory d ON d.partner_kind='vuz'
    AND regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(replace(d.name,'ё','е')),'им.','имени'),'федеральное государственное автономное образовательное учреждение высшего образования',''),'федерального государственного автономного образовательного учреждения высшего образования',''),'федеральное государственное бюджетное образовательное учреждение высшего образования',''),'федерального государственного бюджетного образовательного учреждения высшего образования',''),'фгаоу во',''),'фгбоу во',''),'фгобу во',''),'фгбу во',''),'фгбоу иво',''),'фгбу вон',''),'[^0-9a-zа-я]','','g') = regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(replace(src.name,'ё','е')),'им.','имени'),'федеральное государственное автономное образовательное учреждение высшего образования',''),'федерального государственного автономного образовательного учреждения высшего образования',''),'федеральное государственное бюджетное образовательное учреждение высшего образования',''),'федерального государственного бюджетного образовательного учреждения высшего образования',''),'фгаоу во',''),'фгбоу во',''),'фгобу во',''),'фгбу во',''),'фгбоу иво',''),'фгбу вон',''),'[^0-9a-zа-я]','','g')
  ORDER BY src.name,(d.verification_status='verified') DESC,d.id
)
UPDATE education_directory d SET
  program_codes = src.program_codes,
  programs_source_url = 'https://adm.digital.gov.ru/app/uploads/2026/05/6027f0_perechen-oo-vo-realizuyushhih-it-speczialnosti.pdf',
  programs_checked_at = now(),
  listed_in_mincifry_order_27 = TRUE,
  updated_at = now()
FROM exact_matches src
WHERE d.id=src.id;

-- The order contains short names but no region or licensing attributes.
-- Such rows enter the review queue; administrators enrich and verify them later.
  name,partner_kind,region,source,registry_record_id,source_url,registry_updated_at,
  verification_status,program_codes,programs_source_url,programs_checked_at,
  listed_in_mincifry_order_27
)
SELECT src.name,'vuz','Регион не указан','Перечень ОО ВО Минцифры России, приказ № 27 от 22.01.2026',
  'mincifry-order-27-2026:' || md5(src.name),
  'https://adm.digital.gov.ru/app/uploads/2026/05/6027f0_perechen-oo-vo-realizuyushhih-it-speczialnosti.pdf',DATE '2026-01-22','pending',src.program_codes,
  'https://adm.digital.gov.ru/app/uploads/2026/05/6027f0_perechen-oo-vo-realizuyushhih-it-speczialnosti.pdf',now(),TRUE
FROM mincifry_order_27_import src
WHERE NOT EXISTS (
  SELECT 1 FROM education_directory d
  WHERE d.partner_kind='vuz' AND regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(replace(d.name,'ё','е')),'им.','имени'),'федеральное государственное автономное образовательное учреждение высшего образования',''),'федерального государственного автономного образовательного учреждения высшего образования',''),'федеральное государственное бюджетное образовательное учреждение высшего образования',''),'федерального государственного бюджетного образовательного учреждения высшего образования',''),'фгаоу во',''),'фгбоу во',''),'фгобу во',''),'фгбу во',''),'фгбоу иво',''),'фгбу вон',''),'[^0-9a-zа-я]','','g') = regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(replace(src.name,'ё','е')),'им.','имени'),'федеральное государственное автономное образовательное учреждение высшего образования',''),'федерального государственного автономного образовательного учреждения высшего образования',''),'федеральное государственное бюджетное образовательное учреждение высшего образования',''),'федерального государственного бюджетного образовательного учреждения высшего образования',''),'фгаоу во',''),'фгбоу во',''),'фгобу во',''),'фгбу во',''),'фгбоу иво',''),'фгбу вон',''),'[^0-9a-zа-я]','','g')
)
ON CONFLICT (name,partner_kind,region) DO UPDATE SET
  program_codes=EXCLUDED.program_codes,
  programs_source_url=EXCLUDED.programs_source_url,
  programs_checked_at=EXCLUDED.programs_checked_at,
  listed_in_mincifry_order_27=TRUE,
  updated_at=now();

CREATE INDEX education_directory_mincifry_order_27_idx
  ON education_directory(listed_in_mincifry_order_27, verification_status)
  WHERE listed_in_mincifry_order_27;

COMMENT ON COLUMN education_directory.listed_in_mincifry_order_27 IS
  'Organization is explicitly listed in the Minцифры Order No. 27 table supplied from the official PDF.';
